ALTER TABLE "spaces" ADD CONSTRAINT "name_not_reserved" CHECK (lower(btrim(regexp_replace("spaces"."name", '[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+', ' ', 'g'))) not in ('private', 'privado'));